// @ai-generated
// Qariah: the fork's i18n overlay (Sprint 47, Pass C).
//
// Qariah reuses upstream Bayaan's locale files as they are. Where Qariah needs
// different copy for an EXISTING upstream key, the new value goes into an
// override file here, never into `i18n/locales/<lang>/<namespace>.json`, so a
// weekly upstream sync never conflicts on a locale file:
//
//   i18n/overrides/en.json  hand-kept: Qariah's English wording for an upstream
//                           key (for example "Browse by Rewaya").
//   i18n/overrides/ar.json  generated by `scripts/i18n-qariah-from-review.mjs
//                           --section=U` from the Arabic review pack: the
//                           feminine forms of upstream's reciter strings.
//
// Each file is keyed by namespace, then by the upstream key path:
//   {"home": {"home": {"exploreByRewayah": "Browse by Rewaya"}}}
//
// An override can only REPLACE an upstream value. It never adds a key, so the
// typed `t()` (types/i18next.d.ts) stays exactly upstream's plus the `qariah`
// namespace. `i18n/__tests__/qariah.test.ts` fails when an override names a
// key that upstream does not have.
//
// Qariah-only text does not belong here: it lives in the `qariah` namespace
// (`i18n/locales/<lang>/qariah.json`).
//
// Candidate upstream seam: a fork i18n overlay in Bayaan would make this file
// unnecessary (DIVERGENCE_LEDGER.md, 2026-10-19).
import enOverrides from './overrides/en.json';
import arOverrides from './overrides/ar.json';

/** A locale tree: nested objects with string leaves. */
export type LocaleTree = {readonly [key: string]: string | LocaleTree};

/** Overrides per language, each keyed by namespace. */
export const QARIAH_OVERRIDES: Readonly<
  Record<string, Readonly<Record<string, LocaleTree>>>
> = {
  en: enOverrides,
  ar: arOverrides,
};

/** An override path that does not match an upstream string. */
export interface OverrideProblem {
  language: string;
  path: string;
  reason: 'missing upstream key' | 'shape differs';
}

function mergeTree(
  base: LocaleTree,
  override: LocaleTree,
  language: string,
  path: string,
  problems: OverrideProblem[],
): LocaleTree {
  const out: Record<string, string | LocaleTree> = {...base};
  for (const [key, value] of Object.entries(override)) {
    const keyPath = `${path}.${key}`;
    const current = base[key];
    if (current === undefined) {
      problems.push({language, path: keyPath, reason: 'missing upstream key'});
      continue;
    }
    if (typeof value === 'string' && typeof current === 'string') {
      out[key] = value;
    } else if (typeof value !== 'string' && typeof current !== 'string') {
      out[key] = mergeTree(current, value, language, keyPath, problems);
    } else {
      problems.push({language, path: keyPath, reason: 'shape differs'});
    }
  }
  return out;
}

/**
 * Applies `overrides` to a copy of `resources` and lists the override paths
 * that do not match an upstream string. Those are skipped; the inputs are not
 * changed.
 */
export function applyOverrides(
  resources: Readonly<Record<string, Readonly<Record<string, LocaleTree>>>>,
  overrides: Readonly<Record<string, Readonly<Record<string, LocaleTree>>>>,
): {
  resources: Record<string, Record<string, LocaleTree>>;
  problems: OverrideProblem[];
} {
  const problems: OverrideProblem[] = [];
  const merged: Record<string, Record<string, LocaleTree>> = {};
  for (const [language, namespaces] of Object.entries(resources)) {
    merged[language] = {...namespaces};
    for (const [ns, tree] of Object.entries(overrides[language] ?? {})) {
      const base = namespaces[ns];
      if (base === undefined) {
        problems.push({language, path: ns, reason: 'missing upstream key'});
        continue;
      }
      merged[language][ns] = mergeTree(base, tree, language, ns, problems);
    }
  }
  for (const language of Object.keys(overrides)) {
    if (!(language in resources)) {
      problems.push({language, path: '', reason: 'missing upstream key'});
    }
  }
  return {resources: merged, problems};
}

/**
 * Returns `resources` with Qariah's overrides applied. Typed as the identity,
 * so `CustomTypeOptions` keeps upstream's exact key types. A path that does
 * not match is skipped here (never a crash at start-up); the Jest test is
 * what fails on it.
 */
export function withQariahOverrides<T extends object>(resources: T): T {
  return applyOverrides(
    resources as unknown as Record<string, Record<string, LocaleTree>>,
    QARIAH_OVERRIDES,
  ).resources as unknown as T;
}
